  "private": true,
  "description": "AI agent platform: LLM gateway, broker, Temporal orchestrator, nova-worker harness, Slack app.",
  "type": "module",
  "workspaces": ["shared", "gateway", "broker", "orchestrator", "harness", "slack-app"],
  "scripts": {
    "build": "npm run build --workspaces --if-present",
    "lint": "eslint .",
    "typecheck": "npm run typecheck --workspaces --if-present",
    "test": "node --import tsx --test \"*/test/**/*.test.ts\"",
    "check": "npm run lint && npm run typecheck && npm test && npm run build"
  },
  "engines": {
    "node": ">=24"
  },
  "devDependencies": {
    "@types/node": "24.12.2",
    "eslint": "10.8.0",
