// ai-agents/orchestrator/src/activities/sandbox.ts — sketch. Activities may use Node APIs; workflow code may not.
import { heartbeat } from "@temporalio/activity";
import { AutoScalingClient, AutoScalingServiceException, DetachInstancesCommand, SetDesiredCapacityCommand } from "@aws-sdk/client-auto-scaling";
import { CreateTagsCommand, EC2Client } from "@aws-sdk/client-ec2";
import { setTimeout as sleep } from "node:timers/promises";

const asg = new AutoScalingClient({});
const ec2 = new EC2Client({});
/** Take a warm VM of the right size, detach it, and tag it as this run's. Temporal owns it after this. */
export const acquireSandbox = async (req: ClaimRequest): Promise<Sandbox> => {
  const existing = await findInstance({ "ai-agents:run-id": req.runId }); // safe to retry
  if (existing) return existing;
  const group = `ai-agents-sandbox-${req.size}${req.spot ? "-spot" : ""}`;
  const before = await inServiceIds(group);
  await asg.send(new SetDesiredCapacityCommand({ AutoScalingGroupName: group, DesiredCapacity: (await desired(group)) + 1, HonorCooldown: false }));
  for (;;) {
    heartbeat("waiting for a warm VM");
    for (const instanceId of (await inServiceIds(group)).filter((id) => !before.includes(id))) {
      try { // two claims may race for one VM: the loser's detach fails and it tries the next
        await asg.send(new DetachInstancesCommand({ InstanceIds: [instanceId], AutoScalingGroupName: group, ShouldDecrementDesiredCapacity: true }));
      } catch (err) {
        if (err instanceof AutoScalingServiceException) continue;
        throw err;
      }
      await ec2.send(new CreateTagsCommand({ Resources: [instanceId], Tags: [
        { Key: "ai-agents:run-id", Value: req.runId },
        { Key: "ai-agents:agent", Value: req.agent },
        { Key: "ai-agents:jira", Value: req.jiraKey ?? "-" },
        { Key: "ai-agents:lease-until", Value: leaseUntil({ hours: 2 }) }, // renewed while the run lives
      ] }));
      return { instanceId, size: req.size, spot: req.spot, runId: req.runId };
    }
    await sleep(5_000);
  }
};

// ai-agents/harness/src/session.ts — sketch. No key in the VM: the gateway adds it.
import { createSdkMcpServer, type Options, type SessionStore } from "@anthropic-ai/claude-agent-sdk/core";

export const buildOptions = (task: Task, hooks: Options["hooks"], store: SessionStore): Options => {
  const route = routeFor(task.job); // Opus 5.5 at medium unless the plan picked another row (G3-33)
  return {
    model: route.model,
    effort: route.effort,
    cwd: "/work/fcp", // the same on every VM, so a stored session resumes anywhere
    settingSources: ["project"], // fcp's CLAUDE.md/AGENTS.md and .claude/; managed settings load anyway
    allowedTools: ["Read", "Grep", "Glob", "Edit", "Write", "Bash", "TodoWrite",
      "Workflow", "mcp__nova__ask_human", "mcp__nova__post_progress", "mcp__nova__kb_search"], // Workflow: G4-09, G4-19
    disallowedTools: ["WebFetch", "WebSearch"], // the proxy blocks the web anyway; say so up front
    permissionMode: "dontAsk", // nobody sits at a prompt: anything not allowed is refused
    mcpServers: { nova: createSdkMcpServer({ name: "nova", tools: [askHuman, postProgress, kbSearch] }) }, // call the broker
    hooks, // walls (G3-21) and the progress watcher (G3-32)
    sessionStore: store, // transcripts to S3 through the broker (G3-23)
    resume: task.resumeSessionId, // after a question, or on a fresh VM
    pathToClaudeCodeExecutable: "/usr/local/bin/claude", // the pinned binary the nightly smoke test passed (G3-14)
    env: {
      ...process.env, // env REPLACES the subprocess environment, so spread it first
      ANTHROPIC_BASE_URL: GATEWAY_URL, // https://gateway.ai-agents.example.com:8443 over PrivateLink
      ANTHROPIC_AUTH_TOKEN: task.gatewayToken, // G0-13 run token: not an Anthropic key, dies with the run
      ...stepEnv(task.run, task.step), // G1-14: OTel tags and the x-ai-agents-step header; agent, jira, run ride in the token
      ENABLE_TOOL_SEARCH: "true", // off by default behind a gateway (G0-13)
      CLAUDE_CODE_MAX_SUBAGENT_SPAWN_DEPTH: "1", // helpers can't start helpers
      CLAUDE_CODE_WORKFLOW_MAX_CONCURRENT_AGENTS: String(WORKFLOW_AGENTS[task.size]), // 3 / 6 / 12
      ...ROUTING_ENV, // output limit and cache TTL (G3-33)
    },
    // No maxTurns, no maxBudgetUsd, no taskBudget: work is never cut off mid-run.
  };
};

// ai-agents/orchestrator/src/activities/run.ts — sketch
import { ApplicationFailure, heartbeat } from "@temporalio/activity";
import { EC2Client, StopInstancesCommand, TerminateInstancesCommand } from "@aws-sdk/client-ec2";
import { setTimeout as sleep } from "node:timers/promises";
const ec2 = new EC2Client({});

/** Start the harness if needed, then follow it. Returns when the run ends, asks, or dies. */
export const workInSandbox = async (vm: Sandbox, task: Task): Promise<RunOutcome> => {
  await ensureHarnessRunning(vm, task); // systemd-run ... nova-worker run over SSM; a retry re-attaches instead of starting twice
  let lastLease = 0;
  for (;;) {
    const beat = await brokerInternal.get<Heartbeat>(`/internal/runs/${task.runId}/heartbeat`);
    heartbeat({ step: beat.step, progress: beat.progress }); // Temporal: we're alive
    if (["done", "needs_answer", "preempted", "failed"].includes(beat.state)) return toOutcome(beat);
    // No "I'm alive" for 5 minutes: the VM or the harness is gone.
    if (beat.age_s > 300) throw ApplicationFailure.create({ message: "no heartbeat for 5 minutes", type: "SandboxDead", nonRetryable: true });
    if (performance.now() - lastLease > 300_000) {
      await tag(vm, { "ai-agents:lease-until": leaseUntil({ hours: 2 }) }); // the sweeper leaves live runs alone
      lastLease = performance.now();
    }
    await sleep(30_000);
  }
};

/** Waiting on a person: stop the VM and keep its disk (about $0.01/h instead of $0.42/h for full). */
export const parkSandbox = async (vm: Sandbox): Promise<void> => {
  await ec2.send(new StopInstancesCommand({ InstanceIds: [vm.instanceId] }));
  await tag(vm, { "ai-agents:state": "parked", "ai-agents:lease-until": leaseUntil({ hours: 73 }) });
};

export const releaseSandbox = async (vm: Sandbox): Promise<void> => { // end of the run: no reuse, ever
  await brokerInternal.delete(`/internal/runs/${vm.runId}`); // the capability stops working
  await ec2.send(new TerminateInstancesCommand({ InstanceIds: [vm.instanceId] })).catch((err: Error) => {
    if (err.name !== "InvalidInstanceID.NotFound") throw err; // a VM that is already gone is fine
  });
};

// ai-agents/harness/src/hooks.ts — sketch. Walls only; how to work stays guidance.
import type { HookCallback, HookJSONOutput, PreToolUseHookInput, StopHookInput } from "@anthropic-ai/claude-agent-sdk/core";

const PROTECTED = loadGlobs("/opt/ai-agents/harness/settings/protected-paths.yaml"); // this repo's block; G0-18 reads the same file
const NEVER_RUN =
  /\b(terraform|tofu|terragrunt)\b.*\b(apply|destroy)\b|argocd\s+app\s+sync|gh\s+workflow\s+run|\/dispatches\b|169\.254\.169\.254/;

export const blockWalls: HookCallback = async (input) => {
  const { tool_name: tool, tool_input } = input as PreToolUseHookInput;
  const args = tool_input as { file_path?: string; notebook_path?: string; command?: string };
  const path = args.file_path ?? args.notebook_path;
  if (path && matches(path, PROTECTED)) {
    return refuse(tool, path, "This file is one of the checks your work is judged by. " +
      "Add a new test instead, or ask the requester with ask_human.");
  }
  if (tool === "Bash" && args.command && NEVER_RUN.test(args.command)) {
    return refuse(tool, args.command, "Agents never apply, destroy, sync or dispatch. Leave a note for a person.");
  }
  return {};
};

export const requireEvidence: HookCallback = async (input) => {
  const missing = planChecks().filter((check) => !ledger.passedAfterLastEdit(check));
  if (missing.length === 0) return {};
  if ((input as StopHookInput).stop_hook_active && ledger.notOurs(missing)) { // flaky, or main was already red
    ledger.flagUnproven(missing); // shown in the PR, not looped on
    return {};
  }
  return { decision: "block", reason: `Before you stop, run these and show them passing: ${missing.join(", ")}` };
};

const refuse = (tool: string, target: string, why: string): HookJSONOutput => {
  ledger.refused(tool, target, why); // listed in the PR (G3-31)
  return { hookSpecificOutput: { hookEventName: "PreToolUse", permissionDecision: "deny", permissionDecisionReason: why } };
};

"""Sandbox sweeper: every 15 minutes, remove VMs and disks that no live run owns. Based on aws-vm-autostop."""
import datetime as dt
import json
import os

import boto3

ec2, autoscaling = boto3.client("ec2"), boto3.client("autoscaling")
DRY_RUN = os.environ.get("DRY_RUN", "true") == "true"  # start dry, like dev-vm-autostop


def handler(event, context):
    now = dt.datetime.now(dt.UTC)
    for inst in managed_instances(states=["running", "stopped"]):  # tag ai-agents:managed=true only
        tags = {t["Key"]: t["Value"] for t in inst.get("Tags", [])}
        if "ai-agents:run-id" in tags and parse(tags.get("ai-agents:lease-until")) < now:
            act("terminate", inst["InstanceId"], "lease expired: no live run owns this VM")
        elif inst["State"]["Name"] == "stopped" and stopped_since(inst) < now - dt.timedelta(hours=72):
            act("terminate", inst["InstanceId"], "stopped for over 72 h; its work is already saved")
        elif "aws:autoscaling:groupName" in tags and inst["LaunchTime"] < now - dt.timedelta(hours=24):
            act("recycle", inst["InstanceId"], "warm VM older than 24 h; the pool refills from the newest image")
    for vol in managed_volumes(status="available"):
        act("delete-volume", vol["VolumeId"], "orphaned disk")


def act(action: str, resource_id: str, reason: str) -> None:
    print(json.dumps({"action": action, "id": resource_id, "reason": reason, "dry_run": DRY_RUN}))
    if DRY_RUN:
        return
    if action == "terminate":
        ec2.terminate_instances(InstanceIds=[resource_id])
    elif action == "recycle":
        autoscaling.terminate_instance_in_auto_scaling_group(InstanceId=resource_id, ShouldDecrementDesiredCapacity=False)
    else:
        ec2.delete_volume(VolumeId=resource_id)

// ai-agents/harness/src/store.ts — sketch. Adapted from the Agent SDK's S3 reference adapter (examples/session-stores/s3);
// the VM has no AWS keys, so every object goes through a URL the broker presigns for this run's prefix.
import type { SessionKey, SessionStore, SessionStoreEntry } from "@anthropic-ai/claude-agent-sdk/core";

export class BrokerS3SessionStore implements SessionStore {
  readonly #seen = new Set<string>(); // entry uuids already stored
  #seq = 0;
  constructor(private readonly broker: BrokerClient) {}

  #prefix(key: SessionKey): string {
    return `sessions/${key.projectKey}/${key.sessionId}${key.subpath ? `/${key.subpath}` : ""}`;
  }

  async append(key: SessionKey, entries: SessionStoreEntry[]): Promise<void> {
    const fresh = entries.filter((e) => !(typeof e.uuid === "string" && this.#seen.has(e.uuid))); // retried batches repeat
    if (fresh.length === 0) return;
    // Wall-clock time, not a per-process counter: parts written later on another VM must sort after these.
    const name = `${this.#prefix(key)}/part-${Date.now()}-${String(this.#seq++).padStart(6, "0")}.jsonl`;
    const res = await fetch(await this.broker.artifactUrl(name, { write: true }), { method: "PUT", body: fresh.map((e) => JSON.stringify(e)).join("\n") });
    if (!res.ok) throw new Error(`session store PUT failed: ${res.status}`); // the SDK retries, then reports mirror_error
    for (const e of fresh) if (typeof e.uuid === "string") this.#seen.add(e.uuid);
  }

  async load(key: SessionKey): Promise<SessionStoreEntry[] | null> {
    const parts = await this.broker.listArtifacts(`${this.#prefix(key)}/part-`); // sorted by name = by time
    if (parts.length === 0) return null;
    const entries: SessionStoreEntry[] = [];
    for (const part of parts) {
      const body = await (await fetch(await this.broker.artifactUrl(part, { write: false }))).text();
      entries.push(...body.split("\n").filter(Boolean).map((line) => JSON.parse(line) as SessionStoreEntry));
    }
    return entries;
  }

  async listSubkeys(key: { projectKey: string; sessionId: string }): Promise<string[]> {
    return this.broker.listSubkeys(this.#prefix(key)); // restores subagent transcripts too
  }
}

// ai-agents/orchestrator/src/workflows/ticket-to-pr.ts — workflow code: deterministic; no Node APIs, no fetch, no Date.now().
import { CancellationScope, condition, defineSignal, setHandler, workflowInfo } from "@temporalio/workflow";
import type { Handoff, PlanDecision, RunState } from "@rhinohealth/ai-agents-shared"; // Handoff: { key, requester, drill? } (G4-04)
import { act } from "../policies.js"; // proxied activities: 7-day start-to-close as a safety net, 2-minute heartbeats (G3-29)
import { waitForPerson } from "../waiting.js"; // reminders, then parking (G3-38); no VM runs while we wait
export const decidePlan = defineSignal<[PlanDecision]>("decidePlan"); // Slack buttons (G3-35)
export const answerQuestion = defineSignal<[text: string, by: string]>("answerQuestion"); // a reply in the ticket's thread
export async function ticketToPr(t: Handoff): Promise<string> { // workflow ID "nova:RH-1234": one run per ticket (G3-25)
  const run: RunState = { stopped: false }; // shared with G4-12's grill block and the Stop button (G3-38)
  let decision: PlanDecision | undefined;
  setHandler(decidePlan, (d) => { decision = d; });
  setHandler(answerQuestion, (text) => { run.answer = text; });
  const base = await act.mainHead(); // plan and build start from the same main commit
  const inSandbox = async (task: Task, size: Size): Promise<RunResult> => {
    const vm = await act.acquireSandbox({ runId: workflowInfo().runId, size, agent: "nova", jiraKey: t.key });
    try {
      await act.freshenSandbox(vm, base);
      run.answer = undefined; // cleared before the run, so a quick reply to its question is never lost
      let result = await act.workInSandbox(vm, task); // heartbeats; no work-time limit
      while (result.needsAnswer) {
        const idle = !(await condition(() => run.answer !== undefined, "10 minutes")); // no answer yet
        if (idle) await act.parkSandbox(vm); // stop the VM and keep its disk while a person thinks (G3-20)
        if (!(await waitForPerson(run, "question", () => run.answer !== undefined, t))) return { ...result, parked: true };
        if (idle) await act.wakeSandbox(vm); // start it again, freshen if main moved (G3-20)
        const reply = run.answer ?? ""; run.answer = undefined;
        result = await act.workInSandbox(vm, resumeTask(task, result.sessionId, reply));
      }
      return result;
    } finally {
      await CancellationScope.nonCancellable(() => act.releaseSandbox(vm)); // always: no VM is left behind
    }
  };
  const plan = await inSandbox(planTask(t), "lite"); // plan small
  if (plan.parked) return "parked";
  await act.postPlan(t, plan);
  if (!(await waitForPerson(run, "plan", () => decision !== undefined, t))) return "parked"; // remind at 1 day, park at 3
  if (decision?.kind !== "approve") return "stopped";
  const built = await inSandbox(buildTask(t, plan), "full"); // build big
  return built.parked ? "parked" : built.prUrl;
}

// ai-agents/orchestrator/src/fanout.ts — sketch. Only the orchestrator starts runs.
import type { Client, Workflow } from "@temporalio/client";
import { defineSearchAttributeKey, SearchAttributeType, TypedSearchAttributes, WorkflowIdConflictPolicy } from "@temporalio/common";

const AGENT = defineSearchAttributeKey("Agent", SearchAttributeType.KEYWORD);

export const startRun = (client: Client, agent: string, thing: string, wf: string | Workflow, ...args: unknown[]) =>
  client.workflow.start(wf, {
    workflowId: `${agent}:${thing}`, // nova:RH-1234 | cifix:fcp:<fingerprint> | upgrade:fcp:pr-<n> | bugfix:RH-1240
    taskQueue: `ai-agents-${agent}`, // one queue per agent: nobody starves anybody
    workflowIdConflictPolicy: WorkflowIdConflictPolicy.USE_EXISTING, // a second trigger joins the open run
    typedSearchAttributes: new TypedSearchAttributes([{ key: AGENT, value: agent }]),
    args,
  });

// ai-agents/orchestrator/src/workflows/slots.ts — workflow code. ID "slots:<agent>"; lives forever, continues-as-new now and then.
import { condition, continueAsNew, defineSignal, getExternalWorkflowHandle, setHandler, workflowInfo } from "@temporalio/workflow";

export const SLOTS: Record<string, number> = { nova: 3, cifix: 2, upgrade: 2, flaky: 1, bugfix: 2, health: 1, security: 1 }; // VMs in parallel per agent, to start
export const request = defineSignal<[workflowId: string]>("request");
export const release = defineSignal<[workflowId: string]>("release"); // on park (VM stopped) and at the end of a run
export const slotGranted = defineSignal("slotGranted");

export async function slots(agent: string, holders: string[] = [], waiting: string[] = []): Promise<void> {
  setHandler(request, (id) => { waiting.push(id); });
  setHandler(release, (id) => { holders = holders.filter((h) => h !== id); });
  while (workflowInfo().historyLength < 5000) {
    await condition(() => waiting.length > 0 && holders.length < (SLOTS[agent] ?? 1));
    const holder = waiting.shift()!;
    holders.push(holder);
    await getExternalWorkflowHandle(holder).signal(slotGranted);
  }
  await continueAsNew<typeof slots>(agent, holders, waiting); // carries holders and waiting along
}

// ai-agents/harness/src/checkpoint.ts — sketch
import { execFile } from "node:child_process";
import { readFile } from "node:fs/promises";
import { basename } from "node:path";
import { promisify } from "node:util";

const exec = promisify(execFile);
const git = (...args: string[]) => exec("git", args, { cwd: "/work/fcp" }); // argv, never a shell string

/** Save code, memory and proof outside the VM. Called after every step whose checks pass. */
export const checkpoint = async (run: Run, step: Step): Promise<Checkpoint> => {
  await git("add", "-A");
  const staged = await git("diff", "--cached", "--quiet").then(() => false, () => true); // exit 1: something is staged
  if (staged) {
    // [skip ci]: cloud-ci runs on push to any branch and would take the QA locks at every checkpoint.
    await git("commit", "-m", `wip(${run.jiraKey}): ${step.title} [skip ci]`);
  }
  await git("push", "origin", `HEAD:refs/heads/${run.branch}`); // origin is the broker's git proxy
  const sha = (await git("rev-parse", "HEAD")).stdout.trim();

  await run.broker.upload("notes.md", renderNotes(run, step, sha)); // plan, done, next, questions
  await run.broker.upload(`checkpoints/${String(step.index).padStart(3, "0")}.json`, JSON.stringify({
    sha, step: step.index, session_id: run.sessionId, checks: step.checksPassed,
  }));
  await run.broker.heartbeat({ step: step.index, progress: run.progress(), checkpoint: sha });
  return { sha, sessionId: run.sessionId };
};

/** Screenshots, traces, lab reports and logs go up as they are made, not at the end. */
export const uploadArtifact = async (run: Run, path: string, kind: string): Promise<void> => {
  await run.broker.upload(`artifacts/${kind}/${basename(path)}`, await readFile(path));
  run.manifest.add(kind, basename(path)); // the PR step (G4) links what the QA plan asked for
};

// ai-agents/orchestrator/src/workflows/recovery.ts — workflow code (deterministic), used by ticketToPr and routineRun.
import { ActivityFailure, ApplicationFailure, CancellationScope, log } from "@temporalio/workflow";
import { act } from "../policies.js";

const MAX_LOST_VMS = 2;

/** A VM is only a workbench: if it dies, take a fresh one and carry on from the last checkpoint. */
// RunContext (shared package) = Handoff + { runId, agent, branch, base }, built when ticketToPr or routineRun starts
export const runWithRecovery = async (wf: RunState, t: RunContext, task: Task, size: Size): Promise<RunResult> => {
  for (;;) {
    const vm = await act.acquireSandbox({ runId: t.runId, size, agent: t.agent, jiraKey: t.key });
    try {
      await act.freshenSandbox(vm, wf.checkpoint?.sha ?? t.base);
      return await act.workInSandbox(vm, resumeFrom(task, wf.checkpoint));
    } catch (err) {
      const type = err instanceof ActivityFailure && err.cause instanceof ApplicationFailure ? err.cause.type : undefined;
      if (type !== "SandboxDead" && type !== "LabNotReady") throw err;
      wf.lostVms += 1;
      log.warn("sandbox lost", { run: t.runId, lost: wf.lostVms });
      if (wf.lostVms >= MAX_LOST_VMS) {
        await act.notify(t, "This ticket lost two VMs in a row, so I stopped. " +
          `Branch ${t.branch} and my notes are saved; a person should take a look.`);
        throw ApplicationFailure.create({ message: "two lost VMs", type: "NeedsPerson", nonRetryable: true });
      }
    } finally {
      await CancellationScope.nonCancellable(() => act.releaseSandbox(vm)); // the dead VM is destroyed, never reused
    }
  }
};

// ai-agents/orchestrator/src/triggers/schedules.ts — sketch. One mechanism for every Jira trigger; no public webhooks.
import { type Client, type Workflow, ScheduleAlreadyRunning, ScheduleOverlapPolicy } from "@temporalio/client";
// Registered by G4-04 ("nova") and G5-13 ("bugfix-fe", "bugfix-be"). toStart returns (workflow function, its input), or undefined to skip.
export interface JiraQuery { name: string; agent: string; jql: string; every: string; toStart: (issue: JiraIssue) => Promise<[Workflow, unknown] | undefined> }
export const QUERIES = new Map<string, JiraQuery>();

/** Activity: one poll of one query. startRun refuses a stopped agent (G3-25). */
export const startMatches = async (name: string): Promise<number> => {
  const q = QUERIES.get(name)!;
  const issues = await jira.searchAll(q.jql);
  for (const issue of issues) {
    const start = await q.toStart(issue);
    if (!start) continue; // e.g. no requester found yet (G4-04)
    const [wf, input] = start;
    await startRun(await temporalClient(), q.agent, issue.key, wf, input); // the ID (nova:RH-1234) makes repeats no-ops
  }
  return issues.length;
};

// workflows/poll-jira.ts — workflow code; peopleApis = proxyActivities({ ...SHORT, retry: PEOPLE_APIS }) (G3-29)
export async function pollJira(name: string): Promise<number> {
  return peopleApis.startMatches(name);
}

export const ensureSchedules = async (client: Client): Promise<void> => { // at worker start; safe to run twice
  for (const q of QUERIES.values()) {
    const scheduleId = `poll-jira-${q.name}`;
    const action = { type: "startWorkflow" as const, workflowType: pollJira, args: [q.name],
      workflowId: scheduleId, taskQueue: "ai-agents-orchestrator" };
    const spec = { intervals: [{ every: q.every }] };
    const policies = { overlap: ScheduleOverlapPolicy.SKIP, catchupWindow: q.every }; // an outage doesn't replay a backlog
    await client.schedule.create({ scheduleId, action, spec, policies }).catch(async (err: unknown) => {
      if (!(err instanceof ScheduleAlreadyRunning)) throw err;
      await client.schedule.getHandle(scheduleId).update((prev) => ({ ...prev, action, spec, policies }));
    });
  }
};

// ai-agents/orchestrator/src/policies.ts — workflow-side helpers (deterministic). Timeouts are safety nets, not work limits.
import { proxyActivities, type ActivityOptions, type RetryPolicy } from "@temporalio/workflow";
import type * as activities from "./activities/index.js";

const NEVER_RETRY = ["ScopeDenied", "PlanRejected", "NeedsPerson", "StoppedByPerson"];
export const AWS: RetryPolicy = { initialInterval: "1s", backoffCoefficient: 2, maximumInterval: "1 minute",
  maximumAttempts: 10, nonRetryableErrorTypes: NEVER_RETRY };
export const PEOPLE_APIS: RetryPolicy = { initialInterval: "5s", backoffCoefficient: 2, maximumInterval: "5 minutes",
  nonRetryableErrorTypes: NEVER_RETRY }; // no attempt limit: G3-39 pauses the ticket on long outages
export const HARNESS_STEP: RetryPolicy = { maximumAttempts: 1 }; // recovery (G3-27) decides, not blind retries

export const SHORT: ActivityOptions = { startToCloseTimeout: "5 minutes" };
// startToCloseTimeout is required by the SDK and is NOT a work limit: when 7 days pass, the retry re-attaches to the
// harness still running on the VM. The 2-minute heartbeat is what catches a dead worker.
export const LONG: ActivityOptions = { startToCloseTimeout: "7 days", heartbeatTimeout: "2 minutes" };

/** One place for timeouts and retries, so every workflow behaves the same (by default LONG, with AWS retries). */
export const act = proxyActivities<typeof activities>({ ...LONG, retry: AWS });
export const peopleApis = proxyActivities<typeof activities>({ ...SHORT, retry: PEOPLE_APIS });

