// ai-agents/harness/src/ladder.ts — sketch. Steps in gently; never stops a run for being slow.
const RUNGS = ["nudge", "replan", "think_harder", "fresh_start", "ask_person"] as const; // also the metric's rung label
const STEP_IN_AT = [6, 9, 12, 15, 18]; // tool events with no real progress; tuned from logged verdicts

/** Rungs 1-2: extra context returned by the watcher's PostToolUse hook. */
export const inTurnContext = (verdict: WatcherVerdict): string | undefined => {
  if (verdict.flatFor === STEP_IN_AT[0]) {
    return `Heads up: ${verdict.loopKind} (${verdict.evidence}). Try a different approach, or say what blocks you.`;
  }
  if (verdict.flatFor === STEP_IN_AT[1]) return "Step back: write a short new plan for this step before you do anything else.";
  return undefined;
};

/** Rungs 3-5: at a step boundary, after a checkpoint. Real progress resets the ladder. */
export const betweenTurns = async (run: Run, session: NovaSession, verdict: WatcherVerdict): Promise<void> => {
  if (verdict.flatFor === 0) {
    run.rung = 2;
    return;
  }
  const rung = RUNGS[run.rung];
  if (!rung || verdict.flatFor < STEP_IN_AT[run.rung]!) return;
  metrics.handoffs.add(1, { rung }); // ai_agents_watcher_handoffs_total{rung}
  if (rung === "think_harder") {
    run.route = await rerunOneLevelUp(session, run.step, run.route);
  } else if (rung === "fresh_start") {
    await checkpoint(run, run.step);
    await run.restartSession({ seed: await run.notes() }); // new context, same branch and notes
  } else if (rung === "ask_person") {
    await askHuman(run, `I'm stuck on '${run.step.title}': ${verdict.summary()}. What should I try?`);
  }
  run.rung += 1;
};

// ai-agents/harness/src/backstop.ts — sketch. Runs at step boundaries only, never mid-turn.
const SHADOW = (process.env.NOVA_BACKSTOP_MODE ?? "shadow") === "shadow"; // shadow for the first 4 weeks
const BACKSTOP_USD = Number(process.env.NOVA_BACKSTOP_USD ?? "200"); // far away; set from real data later
const CONTINUE: StepGate = { kind: "continue" };

export const afterStep = async (run: Run): Promise<StepGate> => {
  if (run.elapsedMs() > run.estimate.durationMs * run.nextCheckin) {
    const note = await run.askModel("In 3 short lines: what is taking time, and why is it worth it?");
    await run.broker.postProgress(`Check-in: I'm past my estimate of ${run.estimate.text}.\n${note}`);
    run.nextCheckin *= 2; // at 2x, 4x, 8x ... and keep going unless someone says stop
  }

  const spend = await run.gateway.spend(run.runId); // the gateway is the source of truth
  if (spend < BACKSTOP_USD) return CONTINUE;
  metrics.backstop.add(1, { mode: SHADOW ? "shadow" : "live" }); // ai_agents_backstop_would_pause_total{mode}
  if (SHADOW) {
    log.info("backstop would pause", { run: run.runId, spend_usd: spend });
    return CONTINUE;
  }
  await checkpoint(run, run.step); // nothing is lost; one tap resumes exactly here
  return { kind: "ask", question: "I've used more than the far-away budget for one ticket. Continue?" };
};

// ai-agents/orchestrator/src/waiting.ts — workflow code (deterministic). Waiting costs nothing in Temporal.
import { condition } from "@temporalio/workflow";
import { act } from "./policies.js";

const DAY = 24 * 60 * 60 * 1000;
const WAITS: Record<Wait, [remindAfterMs: number, parkAfterMs: number]> = {
  plan: [1 * DAY, 3 * DAY],
  question: [1 * DAY, 2 * DAY],
  review: [2 * DAY, 14 * DAY],
};

/** True when the person acted; false when the ticket was parked. Stop always wins. */
export const waitForPerson = async (wf: RunState, what: Wait, done: () => boolean, t: Handoff): Promise<boolean> => {
  const [remind, park] = scaled(WAITS[what], t.drill); // minutes instead of days on drill tickets
  // condition() with a timeout resolves false when the timeout passes: a durable timer, no VM running.
  if (await condition(() => done() || wf.stopped, remind)) return !wf.stopped;
  await act.notify(t, REMINDERS[what](t.requester)); // Slack thread, Jira if Slack is down
  if (await condition(() => done() || wf.stopped, park - remind)) return !wf.stopped;
  await act.parkTicket(t, PARK_NOTES[what]); // G4 decides the Jira status and assignee
  return false;
};

// ai-agents/orchestrator/src/activities/notify.ts — sketch
import { ApplicationFailure } from "@temporalio/activity";

/** Reach the requester somewhere. Slack down -> Jira; Jira down -> Slack; both down -> retry later. */
export const notify = async (t: Handoff, text: string, prefer: "slack" | "jira" = "slack"): Promise<string> => {
  const order = prefer === "slack" ? [postToThread, commentOnJira] : [commentOnJira, postToThread];
  const errors: string[] = [];
  for (const send of order) {
    try {
      await send(t, text);
      return send.name;
    } catch (err) {
      if (!(err instanceof ServiceDown)) throw err; // ServiceDown: 5xx, timeouts, or still rate-limited after retries
      errors.push(`${send.name}: ${err.message}`);
    }
  }
  throw ApplicationFailure.create({ message: "Slack and Jira are both down", details: errors, type: "BothDown" }); // retried with back-off
};

// ai-agents/orchestrator/src/workflows/outage.ts — workflow code (deterministic): durable timers, no VM running.
import { proxyActivities, sleep } from "@temporalio/workflow";
const OUTAGE_BACKOFF = ["15 minutes", "30 minutes", "1 hour"];
const { gatewayHealthy } = proxyActivities<typeof activities>({ ...SHORT, retry: HARNESS_STEP });

/** Claude was down for 15 minutes: the harness saved a checkpoint and exited. Park, wait, resume. */
export const waitOutOutage = async (t: Handoff, vm: Sandbox): Promise<void> => {
  await act.notify(t, "Claude is unavailable, so I saved my work and paused. I'll carry on by myself.");
  await act.parkSandbox(vm);
  for (let attempt = 0; ; attempt++) {
    await sleep(OUTAGE_BACKOFF[Math.min(attempt, OUTAGE_BACKOFF.length - 1)]!);
    if (await gatewayHealthy()) return; // the caller wakes the VM and resumes the stored session
  }
};

// ai-agents/drills/src/vm.ts — sketch. Runs against the real platform with drill tickets only: `npm run drills -w drills`.
import assert from "node:assert/strict";
import { test } from "node:test";

const drill = await Drill.connect(); // Temporal, Slack, Jira, AWS FIS and metrics clients for the drill tickets
const MINUTES = 60_000;

test("drill: a VM killed mid-run resumes on a fresh VM", async () => {
  const run = await drill.startTicket("DRILL-1", { fixture: "small-fe-fix" });
  const vm = await drill.waitFor(run, { state: "Working" });
  await drill.fis("terminate-instance", { target: vm.instanceId }); // an AWS FIS experiment template
  await drill.waitFor(run, { state: "Working", notVm: vm.instanceId, withinMs: 10 * MINUTES });
  assert.ok(await drill.branchHasCheckpoint(run)); // nothing was lost
  assert.ok((await drill.metric("ai_agents_vm_dead_total", { agent: "nova" })) >= 1);
  assert.equal(await drill.instanceExists(vm.instanceId), false); // the dead VM is gone
});

test("drill: two lost VMs stop and report", async () => {
  const run = await drill.startTicket("DRILL-2", { fixture: "small-fe-fix" });
  for (let i = 0; i < 2; i++) {
    const vm = await drill.waitFor(run, { state: "Working" });
    await drill.fis("terminate-instance", { target: vm.instanceId });
  }
  await drill.waitFor(run, { state: "Needs a person", withinMs: 15 * MINUTES });
  assert.match(await drill.lastThreadMessage(run), /lost two VMs/);
});

test("drill: a Spot warning pushes and retries", async () => {
  const run = await drill.startTicket("DRILL-3", { fixture: "ci-fix", spot: true });
  const vm = await drill.waitFor(run, { state: "Working" });
  await drill.fis("send-spot-interruption", { target: vm.instanceId });
  await drill.waitFor(run, { state: "Working", notVm: vm.instanceId, withinMs: 10 * MINUTES });
  assert.ok(await drill.branchHasCheckpoint(run));
});
